"""Incoming turn type.

:class:`IncomingTurn` replaces ``UserMessage`` from v1 at the engine
boundary.  It carries only what the engine actually needs: the message text,
the sender ID, and any channel-provided metadata.
"""

from __future__ import annotations

from enum import Enum
from typing import Any

from pydantic import BaseModel, ConfigDict, Field


class IncomingTurnTrigger(str, Enum):
    """Identify what initiated an engine turn."""

    USER_MESSAGE = "user_message"
    SESSION_START = "session_start"
    SILENCE_TIMEOUT = "silence_timeout"
    DTMF = "dtmf"


class IncomingTurn(BaseModel):
    """Represents a single incoming user turn at the engine boundary."""

    model_config = ConfigDict(frozen=True)

    text: str = ""
    sender_id: str
    metadata: dict[str, Any] = Field(default_factory=dict)
    is_voice: bool = False
    """Whether this turn arrived over a voice channel.

    Set by the caller that converts the channel message into an
    ``IncomingTurn`` — the turn itself carries no output channel, so
    modality must be captured at the conversion boundary.
    """
    trigger: IncomingTurnTrigger = IncomingTurnTrigger.USER_MESSAGE
    dtmf_field_name: str | None = Field(default=None, exclude=True, repr=False)
    """Field for which the DTMF handler collected this turn's digits."""
    suppress_llm_user_message: bool = False
    """When ``True``, omit this turn's ``text`` from the LLM prompt.

    Set after a handled valid static ``set:`` button tap so the model does not
    interpret the raw payload string, and on a ``SESSION_START`` turn so the
    pending first user message is not answered by the session-start skill. The
    matching ``UserUttered`` remains in tracker history but is omitted when that
    history is replayed into an LLM prompt. ``llm_user_message`` may replace the
    omitted text with safe prompt copy. Invalid ``set:`` shapes without a title
    end via ``skip_set_memory_button_tap`` instead of a prompt stand-in.
    """
    llm_user_message: str | None = None
    """Optional stand-in user copy for the LLM when ``text`` is suppressed.

    The sanitized button label, so the model sees what the person chose
    without the raw ``set:`` payload. Set after a successful write when the
    channel sent a title, and after a rejecting memory validation tool.
    """
    set_memory_button_written_key: str | None = None
    """Memory key a successful ``set:`` tap wrote on this turn.

    Set only when the write is kept. The prompt uses it for an engine
    instruction that the value is already stored. Unset on taps that do not
    save, and on later turns.
    """
    skip_set_memory_button_tap: bool = False
    """When ``True``, end the turn with the packaged set-button notice.

    Covers unusable ``set:`` taps (not offered on the latest agent message,
    not writable, no active scope, missing field, value that fails coerce,
    malformed payload without a title, write-once denial). The orchestrator
    utters ``utter_set_memory_button_skipped`` and does not invoke the LLM, so a
    parked collect step does not BREAK with the raw payload as user copy.
    """


def incoming_turn_from_user_message(message: Any) -> IncomingTurn:
    """Convert a v1 ``UserMessage`` into an :class:`IncomingTurn`.

    The single seam where channel-level types cross into the engine.
    *message* is typed ``Any`` to avoid importing channel modules here.
    """
    # Local import: voice_stream pulls optional audio dependencies that must
    # not load on every skills import.
    from rasa.core.channels.voice_stream.voice_channel import VoiceOutputChannel

    is_voice = message.is_voice or isinstance(
        message.output_channel, VoiceOutputChannel
    )
    dtmf_field_name = message.dtmf_field_name
    is_dtmf = dtmf_field_name is not None
    trigger = IncomingTurnTrigger.DTMF if is_dtmf else IncomingTurnTrigger.USER_MESSAGE
    return IncomingTurn(
        text=message.text or "",
        sender_id=message.sender_id or "",
        metadata=message.metadata or {},
        is_voice=is_voice,
        trigger=trigger,
        dtmf_field_name=dtmf_field_name,
    )
